class BoundedValue:
    def __init__(self, value: float):
        self.value = value

    @property
    def value(self) -> float:
        return self._val

    @value.setter
    def value(self, v: float):
        if not (0.0 <= v <= 1.0):
            raise ValueError('Must be between 0.0 and 1.0')
        self._val = v
